Translate the following MS C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <cmath>
using namespace std;

int gcd_calc(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

int main() {
    int a_in, b_in, limit_in;
    cin >> a_in >> b_in >> limit_in;
    double target_ratio = (double)a_in / b_in;
    double min_diff = 1e9;
    int best_num = 0, best_den = 1;

    for (int i = 1; i <= limit_in; ++i) {
        int b_value = (long long)a_in * i / b_in;
        double candidates[] = {
            (double)b_value / i,
            (double)(abs(b_value - 1)) / i,
            (double)(b_value + 1) / i
        };
        int candidate_nums[] = {b_value, abs(b_value - 1), b_value + 1};

        for (int j = 0; j < 3; ++j) {
            double diff = fabs(target_ratio - candidates[j]);
            if (diff < min_diff) {
                min_diff = diff;
                best_num = candidate_nums[j];
                best_den = i;
            }
        }
    }

    if (fabs(1.0 - target_ratio) <= (fabs((double)best_num / best_den) - target_ratio) + 1e-9) {
        best_num = 1;
        best_den = 1;
    }

    int g = gcd_calc(best_num, best_den);
    cout << best_num / g << "/" << best_den / g << endl;
    return 0;
}
